AS $function$
DECLARE sides jsonb;k record;
BEGIN
 IF TG_OP='UPDATE' AND (OLD.org_id,OLD.channel,OLD.phone_e164) IS NOT DISTINCT FROM (NEW.org_id,NEW.channel,NEW.phone_e164) THEN RETURN NULL;END IF;
