  INSERT INTO inbox_safety.routes(org_id,phone_e164,generation) VALUES(k.o,k.p,1) ON CONFLICT(org_id,phone_e164) DO UPDATE SET generation=inbox_safety.routes.generation+1;
 END LOOP;
