CREATE OR REPLACE FUNCTION inbox_saved_actions."create"(o uuid, u uuid, name text, definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE row inbox_saved_actions.definitions;
BEGIN
 PERFORM inbox_action_api.authorize(o,u);
 IF name IS NULL OR length(btrim(name)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_NAME';END IF;
 PERFORM inbox_saved_actions.validate_definition(o,definition);
 INSERT INTO inbox_saved_actions.definitions(org_id,id,requester_id,version,name,schema_version,definition,is_active)
 VALUES(o,gen_random_uuid(),u,1,btrim(name),1,definition,true) RETURNING * INTO row;
 RETURN jsonb_build_object('id',row.id,'version',row.version,'name',row.name,'definition',row.definition,'org_id',row.org_id,'requester_id',row.requester_id,'is_active',row.is_active,'created_at',row.created_at);
END $function$

CREATE OR REPLACE FUNCTION inbox_saved_actions.deactivate(o uuid, u uuid, target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE current inbox_saved_actions.definitions;row inbox_saved_actions.definitions;
BEGIN
 PERFORM inbox_action_api.authorize(o,u);
 IF target_id IS NULL THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_NOT_FOUND';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sandra:inbox:saved_action:v1:'||o::text||':'||u::text||':'||target_id::text,0));
 SELECT * INTO current FROM inbox_saved_actions.definitions WHERE org_id=o AND requester_id=u AND id=target_id ORDER BY version DESC LIMIT 1;
 IF NOT FOUND OR NOT current.is_active THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_NOT_FOUND';END IF;
 -- Tombstone version only. Never mutates current/prior rows, never touches
 -- an already accepted operation (which only holds a frozen, detached copy).
 INSERT INTO inbox_saved_actions.definitions(org_id,id,requester_id,version,name,schema_version,definition,is_active)
 VALUES(o,target_id,u,current.version+1,current.name,current.schema_version,current.definition,false) RETURNING * INTO row;
 RETURN jsonb_build_object('id',row.id,'version',row.version,'is_active',row.is_active);
END $function$

CREATE OR REPLACE FUNCTION inbox_saved_actions.get(o uuid, u uuid, target_id uuid, target_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE row inbox_saved_actions.definitions;
BEGIN
 PERFORM inbox_action_api.authorize(o,u);
 IF target_id IS NULL OR target_version IS NULL OR target_version<1 THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_NOT_FOUND';END IF;
 SELECT * INTO row FROM inbox_saved_actions.definitions WHERE org_id=o AND requester_id=u AND id=target_id AND version=target_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_NOT_FOUND';END IF;
 IF EXISTS(SELECT 1 FROM inbox_saved_actions.definitions WHERE org_id=o AND requester_id=u AND id=target_id AND version>target_version) THEN
  RAISE EXCEPTION 'INBOX_SAVED_ACTION_STALE_VERSION';
 END IF;
 IF NOT row.is_active THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_NOT_FOUND';END IF;
 PERFORM inbox_saved_actions.validate_definition(o,row.definition);
 RETURN jsonb_build_object('id',row.id,'version',row.version,'name',row.name,'definition',row.definition,'org_id',row.org_id,'requester_id',row.requester_id,'is_active',row.is_active,'created_at',row.created_at);
END $function$

CREATE OR REPLACE FUNCTION inbox_saved_actions.list(o uuid, u uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM inbox_action_api.authorize(o,u);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'version',d.version,'name',d.name,'definition',d.definition,'created_at',d.created_at) ORDER BY d.name,d.id),'[]') INTO result
 FROM (SELECT DISTINCT ON (id) * FROM inbox_saved_actions.definitions WHERE org_id=o AND requester_id=u ORDER BY id,version DESC) d
 WHERE d.is_active;
 RETURN jsonb_build_object('items',result);
END $function$

CREATE OR REPLACE FUNCTION inbox_saved_actions.update(o uuid, u uuid, target_id uuid, name text, definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE current inbox_saved_actions.definitions;row inbox_saved_actions.definitions;
BEGIN
 PERFORM inbox_action_api.authorize(o,u);
 IF target_id IS NULL THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_NOT_FOUND';END IF;
 -- Serialize version assignment for this (org,requester,id): the immutable
 -- table has no row to FOR UPDATE-lock across a concurrent INSERT of the
 -- next version, so use the same advisory-lock idiom as
 -- inbox_action_api.lock_request_key.
 PERFORM pg_advisory_xact_lock(hashtextextended('sandra:inbox:saved_action:v1:'||o::text||':'||u::text||':'||target_id::text,0));
 SELECT * INTO current FROM inbox_saved_actions.definitions WHERE org_id=o AND requester_id=u AND id=target_id ORDER BY version DESC LIMIT 1;
 IF NOT FOUND OR NOT current.is_active THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_NOT_FOUND';END IF;
 IF name IS NULL OR length(btrim(name)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_NAME';END IF;
 PERFORM inbox_saved_actions.validate_definition(o,definition);
 INSERT INTO inbox_saved_actions.definitions(org_id,id,requester_id,version,name,schema_version,definition,is_active)
 VALUES(o,target_id,u,current.version+1,btrim(name),1,definition,true) RETURNING * INTO row;
 RETURN jsonb_build_object('id',row.id,'version',row.version,'name',row.name,'definition',row.definition,'org_id',row.org_id,'requester_id',row.requester_id,'is_active',row.is_active,'created_at',row.created_at);
END $function$

CREATE OR REPLACE FUNCTION inbox_saved_actions.validate_definition(o uuid, definition jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE step jsonb;types text[];assignee uuid;reply text;reply_units integer;has_outcome boolean:=false;has_assignment boolean:=false;has_promotion boolean:=false;unknown_action text;has_review_reply boolean:=false;position integer;
BEGIN
 IF jsonb_typeof(definition) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(definition))<>2
  OR definition->'version' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(definition->'steps') IS DISTINCT FROM 'array'
  OR jsonb_array_length(definition->'steps') NOT BETWEEN 1 AND 5 THEN
  RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';
 END IF;
 SELECT array_agg(value->>'type' ORDER BY ordinality) INTO types FROM jsonb_array_elements(definition->'steps') WITH ORDINALITY q(value,ordinality);
 FOR step,position IN SELECT value,ordinality FROM jsonb_array_elements(definition->'steps') WITH ORDINALITY q(value,ordinality) ORDER BY ordinality LOOP
  IF jsonb_typeof(step) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';END IF;
  IF step->>'type'='outcome' THEN
   IF has_outcome OR has_assignment THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_STEP_COMBINATION_UNSUPPORTED';END IF;
   IF (SELECT count(*) FROM jsonb_object_keys(step))<>2 OR NOT(step ? 'value') THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';END IF;
   IF step->>'value'='dnc' THEN RAISE EXCEPTION 'permanent_dnc_not_enabled';END IF;
   IF step->>'value' IS NULL OR step->>'value' NOT IN ('wrong_number','bad_number','not_interested','needs_sequence','nurture','opted_out') THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';END IF;
   has_outcome:=true;
  ELSIF step->>'type'='assign' THEN
   IF has_assignment THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_STEP_COMBINATION_UNSUPPORTED';END IF;
   IF (SELECT count(*) FROM jsonb_object_keys(step))<>2 OR NOT(step ? 'userId') THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';END IF;
   IF jsonb_typeof(step->'userId')='string' THEN
    assignee:=(step->>'userId')::uuid;
    IF NOT EXISTS(SELECT 1 FROM public.memberships WHERE org_id=o AND user_id=assignee AND access_status='active' AND deletion_prepared_at IS NULL AND (access_expires_at IS NULL OR access_expires_at>clock_timestamp())) THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_ASSIGNEE_UNAVAILABLE';END IF;
   ELSIF step->'userId' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';
   END IF;
   has_assignment:=true;
  ELSIF step->>'type'='promote' THEN
   IF has_promotion OR has_assignment THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_STEP_COMBINATION_UNSUPPORTED';END IF;
   IF (SELECT count(*) FROM jsonb_object_keys(step))<>1 THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';END IF;
   has_promotion:=true;
  ELSIF step->>'type' IN ('dismiss_unknown','restore_unknown') THEN
   IF has_assignment OR (unknown_action IS NOT NULL AND unknown_action IS DISTINCT FROM step->>'type') THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_STEP_COMBINATION_UNSUPPORTED';END IF;
   IF (SELECT count(*) FROM jsonb_object_keys(step))<>1 THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';END IF;
   unknown_action:=step->>'type';
  ELSIF step->>'type'='review_reply' THEN
   IF has_review_reply OR position<>array_length(types,1) THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_STEP_COMBINATION_UNSUPPORTED';END IF;
   -- Match ECMAScript String.prototype.trim() exactly. The second argument
   -- contains only WhiteSpace and LineTerminator code points from that set.
   reply:=btrim(step->>'text',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF');
   SELECT char_length(reply)+count(*) INTO reply_units
   FROM generate_series(1,char_length(reply)) AS g(pos)
   WHERE get_byte(convert_to(substr(reply,pos,1),'UTF8'),0)>=240;
   IF (SELECT count(*) FROM jsonb_object_keys(step))<>2 OR NOT(step ? 'text') OR jsonb_typeof(step->'text') IS DISTINCT FROM 'string' OR reply_units NOT BETWEEN 1 AND 1600 THEN RAISE EXCEPTION 'INBOX_SAVED_ACTION_INVALID_DEFINITION';END IF;
   has_review_reply:=true;
  ELSE RAISE EXCEPTION 'INBOX_SAVED_ACTION_STEP_TYPE_DISABLED';
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.inbox_capture_inbound_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE next_revision bigint;
BEGIN
  IF NEW.channel IS DISTINCT FROM 'sms' OR NEW.direction IS DISTINCT FROM 'inbound'
     OR NEW.org_id IS NULL OR NEW.conversation_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.org_id, NEW.conversation_id, NEW.channel, NEW.direction)
       IS NOT DISTINCT FROM (OLD.org_id, OLD.conversation_id, OLD.channel, OLD.direction) THEN
      RETURN NULL;
    END IF;
  END IF;
  INSERT INTO public.inbox_inbound_heads(org_id, conversation_id, revision)
    VALUES (NEW.org_id, NEW.conversation_id, 1)
  ON CONFLICT (org_id, conversation_id) DO UPDATE
    SET revision = public.inbox_inbound_heads.revision + 1
  RETURNING revision INTO next_revision;
  -- The original source write already holds its tuple lock. The head lock and
  -- this stamp remain in that same transaction through commit or rollback.
  UPDATE public.messages SET inbox_inbound_revision = next_revision
    WHERE id = NEW.id AND org_id = NEW.org_id AND conversation_id = NEW.conversation_id;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.inbox_counts_v2(org_id uuid, filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a jsonb;after_access jsonb;f jsonb;result jsonb;
BEGIN
 a:=inbox_bridge.authorize_serving(org_id);f:=inbox_bridge.normalize_filter(filter);
 SELECT inbox_bridge.counts_typed(org_id,(a->>'user_id')::uuid,f) INTO result;
 after_access:=inbox_bridge.authorize_serving(org_id);
 IF (after_access->>'user_id',after_access->>'session_id',after_access->>'access_epoch') IS DISTINCT FROM (a->>'user_id',a->>'session_id',a->>'access_epoch') THEN RAISE EXCEPTION 'INBOX_ACCESS_CHANGED' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('counts',result,'as_of',statement_timestamp(),'access_epoch',a->>'access_epoch');
END $function$

CREATE OR REPLACE FUNCTION public.inbox_create_workset_v2(org_id uuid, filter jsonb, "limit" integer, replaces_scope_id uuid DEFAULT NULL::uuid, cursor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
 SET statement_timeout TO '20s'
AS $function$
DECLARE
  a jsonb;
  u uuid;
  sid uuid;
  e bigint;
  now_at timestamptz;
  prior inbox_bridge.worksets;
  created inbox_bridge.worksets;
  ids jsonb;
  gen bigint;
  last_at timestamptz;
  f jsonb;
  n integer := "limit";
  replaces uuid := replaces_scope_id;
  cur inbox_bridge.cursor_context;
  page_rows jsonb;
  last_row jsonb;
  next_id uuid;
BEGIN
  f := inbox_bridge.normalize_filter(filter);
  IF n IS NULL OR n < 1 OR n > 500 THEN
    RAISE EXCEPTION 'INBOX_INVALID_WORKSET' USING ERRCODE = '22023';
  END IF;

  a := inbox_bridge.authorize_serving(org_id);
  u := (a->>'user_id')::uuid;
  sid := (a->>'session_id')::uuid;

  -- Persistent actor row serializes generation allocation, access capture,
  -- cursor-origin validation, and replacement.
  PERFORM 1 FROM inbox_bridge.access_epochs WHERE user_id = u FOR UPDATE;
  a := inbox_bridge.authorize_serving(org_id);
  e := (a->>'access_epoch')::bigint;
  now_at := clock_timestamp();

  SELECT max(generation), max(created_at)
    INTO gen, last_at
    FROM inbox_bridge.worksets
   WHERE user_id = u AND session_id = sid;
  IF last_at > now_at - interval '1 second' THEN
    RAISE EXCEPTION 'INBOX_GENERATION_RATE' USING ERRCODE = '55000';
  END IF;

  IF replaces IS NOT NULL THEN
    SELECT * INTO prior FROM inbox_bridge.worksets WHERE id = replaces FOR UPDATE;
    IF NOT FOUND
       OR prior.user_id <> u
       OR prior.session_id <> sid
       OR prior.org_id <> org_id
       OR prior.access_epoch <> e
       OR prior.revoked THEN
      RAISE EXCEPTION 'INBOX_REPLACEMENT_DENIED' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF (
    SELECT count(*)
      FROM inbox_bridge.worksets
     WHERE user_id = u
       AND session_id = sid
       AND NOT revoked
       AND expires_at > now_at
       AND id IS DISTINCT FROM replaces
  ) >= 2 THEN
    RAISE EXCEPTION 'INBOX_GENERATION_LIMIT' USING ERRCODE = '55000';
  END IF;

  IF cursor_id IS NOT NULL THEN
    SELECT w.id, w.org_id, w.user_id, w.session_id, w.access_epoch,
           w.generation, w.created_at, w.expires_at, w.filter, w.targets,
           w.handles, w.revoked, c.latest_at AS cursor_at,
           c.target_kind AS cursor_kind, c.target_id AS cursor_target
      INTO cur
      FROM inbox_bridge.cursors c
      JOIN inbox_bridge.worksets w ON w.id = c.scope_id
     WHERE c.id = cursor_id;
    IF NOT FOUND
       OR cur.user_id <> u
       OR cur.session_id <> sid
       OR cur.org_id <> org_id
       OR cur.access_epoch <> e
       OR cur.expires_at <= now_at
       OR cur.revoked
       OR cur.filter IS DISTINCT FROM f THEN
      RAISE EXCEPTION 'INBOX_CURSOR_DENIED' USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT coalesce(
           jsonb_agg(to_jsonb(rows) ORDER BY latest_at DESC NULLS LAST,
                    target_kind, target_id), '[]'::jsonb
         )
    INTO page_rows
    FROM (
      SELECT *
        FROM inbox_bridge.page(
          org_id,
          u,
          f,
          cur.cursor_at,
          cur.cursor_kind,
          cur.cursor_target,
          cursor_id IS NOT NULL,
          n + 1
        )
    ) rows;

  SELECT coalesce(
           jsonb_agg(
             jsonb_build_object('kind', x->>'target_kind', 'id', x->>'target_id')
             ORDER BY ordinal
           ), '[]'::jsonb
         )
    INTO ids
    FROM jsonb_array_elements(page_rows) WITH ORDINALITY elements(x, ordinal)
   WHERE ordinal <= n;

  INSERT INTO inbox_bridge.worksets(
    org_id, user_id, session_id, access_epoch, generation,
    created_at, expires_at, filter, targets, handles,
    source_cursor_id, source_cursor_bound, source_page_limit
  )
  VALUES (
    org_id, u, sid, e, coalesce(gen, 0) + 1,
    now_at,
    least(now_at + interval '15 minutes', (a->>'expires_at')::timestamptz),
    f,
    ids,
    (
      SELECT jsonb_agg(null::text)
        FROM generate_series(1, greatest(1, (jsonb_array_length(ids) + 99) / 100))
    ),
    cursor_id,
    true,
    n
  )
  RETURNING * INTO created;

  IF replaces IS NOT NULL THEN
    UPDATE inbox_bridge.worksets SET revoked = true WHERE id = replaces;
  END IF;

  IF jsonb_array_length(page_rows) > n THEN
    last_row := page_rows->(n - 1);
    INSERT INTO inbox_bridge.cursors(scope_id, latest_at, target_kind, target_id)
    VALUES (
      created.id,
      (last_row->>'latest_at')::timestamptz,
      last_row->>'target_kind',
      (last_row->>'target_id')::uuid
    )
    RETURNING id INTO next_id;
  END IF;

  RETURN inbox_bridge.scope_json(created)
      || jsonb_build_object(
           'next_cursor', next_id,
           'refreshed', cursor_id IS NOT NULL
         );
END;
$function$

CREATE OR REPLACE FUNCTION public.inbox_guard_inbound_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE allocator_owner name;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Even the owner must not supply a fabricated arrival revision at insertion.
    IF NEW.inbox_inbound_revision IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION 'INBOX_REVISION_SERVER_OWNED' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.inbox_inbound_revision IS DISTINCT FROM OLD.inbox_inbound_revision THEN
    SELECT r.rolname INTO STRICT allocator_owner
      FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_roles r ON r.oid = p.proowner
      WHERE p.oid = 'public.inbox_capture_inbound_head()'::pg_catalog.regprocedure;
    IF CURRENT_USER IS DISTINCT FROM allocator_owner THEN
      RAISE EXCEPTION 'INBOX_REVISION_SERVER_OWNED' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inbox_outcome_counts_v1(org_id uuid, filter jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a jsonb;after_access jsonb;f jsonb;result jsonb;
BEGIN
 a:=inbox_bridge.authorize_serving(org_id);f:=inbox_bridge.normalize_filter(filter);
 SELECT inbox_bridge.outcome_counts(org_id,(a->>'user_id')::uuid,f) INTO result;
 after_access:=inbox_bridge.authorize_serving(org_id);
